-- Source: Banco Central do Brasil open datasets (Unicad/STR), retrieved 2026-10-23.
-- See https://dadosabertos.bcb.gov.br/dataset/relacao-de-instituicoes-em-funcionamento-no-pais and https://dadosabertos.bcb.gov.br/dataset/lista-de-participantes-do-str.
ALTER TABLE financial_institutions ADD COLUMN IF NOT EXISTS cnpj TEXT;
ALTER TABLE financial_institutions ADD COLUMN IF NOT EXISTS ispb TEXT;
ALTER TABLE financial_institutions ADD COLUMN IF NOT EXISTS bank_code TEXT;
UPDATE financial_institutions SET name='Banco do Brasil S.A.' WHERE name='Banco do Brasil';
UPDATE financial_institutions SET name='CAIXA ECONOMICA FEDERAL' WHERE name='Caixa Econômica Federal';
UPDATE financial_institutions SET name='ITAÚ UNIBANCO S.A.' WHERE name='Itaú';
UPDATE financial_institutions SET name='Banco Bradesco S.A.' WHERE name='Bradesco';
CREATE INDEX IF NOT EXISTS financial_institutions_name_search_idx ON financial_institutions (LOWER(name));
CREATE INDEX IF NOT EXISTS financial_institutions_bank_code_idx ON financial_institutions (bank_code) WHERE bank_code IS NOT NULL;
